--liquibase formatted sql

-- Demo dataset for local development and demos. Runs only with the Liquibase context `demo`
-- (LIQUIBASE_CONTEXTS=demo). Generated by a script: prices follow BookingService (weekend nights use
-- weekendPrice), points = completed spend / 1,000 VND, property rating = average of seeded reviews.
-- Accounts: admin@ / owner@ / owner2@ / customer@ / customer2@ / customer3@travelmate.vn
-- Passwords: Admin@123, Owner@123, Customer@123.

--changeset travelmate:0100-demo-users context:demo
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:0 SELECT COUNT(*) FROM users WHERE email IN ('admin@travelmate.vn', 'owner@travelmate.vn', 'owner2@travelmate.vn', 'customer@travelmate.vn', 'customer2@travelmate.vn', 'customer3@travelmate.vn')
--comment: Demo accounts (admin, 2 owners, 3 customers) with roles and profiles
--rollback DELETE FROM userdetail WHERE userId LIKE '00000000-0000-4000-8000-%'; DELETE FROM userRoles WHERE userId LIKE '00000000-0000-4000-8000-%'; DELETE FROM users WHERE userId LIKE '00000000-0000-4000-8000-%';

--changeset travelmate:0101-demo-owner-applications context:demo
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:1 SELECT COUNT(*) FROM users WHERE userId = '00000000-0000-4000-8000-000000000001'
--comment: Owner applications: 2 approved, 1 waiting for admin review
--rollback DELETE FROM registerOwner WHERE registerOwnerid IN (1, 2, 3);

--changeset travelmate:0102-demo-properties context:demo
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:1 SELECT COUNT(*) FROM users WHERE userId = '00000000-0000-4000-8000-000000000001'
--comment: 8 approved properties across Vietnam + 1 pending submission, with details, policies, photos and amenities
--rollback DELETE FROM PropertyAmenity WHERE propertyId BETWEEN 1 AND 9; DELETE FROM propertyimage WHERE propertyId BETWEEN 1 AND 9; DELETE FROM property_policies WHERE propertyId BETWEEN 1 AND 9; DELETE FROM property_details WHERE propertyId BETWEEN 1 AND 9; DELETE FROM properties WHERE propertyId BETWEEN 1 AND 9;

--changeset travelmate:0103-demo-rooms context:demo
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:1 SELECT COUNT(*) FROM users WHERE userId = '00000000-0000-4000-8000-000000000001'
--comment: 15 room types (WHOLE rooms for villas/homestays) with photos and amenities
--rollback DELETE FROM RoomAmenity WHERE roomId BETWEEN 1 AND 15; DELETE FROM roomimage WHERE roomId BETWEEN 1 AND 15; DELETE FROM rooms WHERE roomId BETWEEN 1 AND 15;

--changeset travelmate:0104-demo-promotions context:demo
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:1 SELECT COUNT(*) FROM users WHERE userId = '00000000-0000-4000-8000-000000000001'
--comment: Platform (admin) and hotel (owner) promo codes, incl. one rank-gated and one expired
--rollback DELETE FROM promotions WHERE promotionId BETWEEN 1 AND 6;

--changeset travelmate:0105-demo-bookings context:demo
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:1 SELECT COUNT(*) FROM users WHERE userId = '00000000-0000-4000-8000-000000000001'
--comment: Bookings in every state (completed, upcoming, cancelled with refund request), payments, reviews and notifications
--rollback DELETE FROM notifications WHERE user_id LIKE '00000000-0000-4000-8000-%'; DELETE FROM rating WHERE ratingId BETWEEN 1 AND 5; DELETE FROM refund_requests WHERE id = 1; DELETE FROM payment WHERE paymentId BETWEEN 1 AND 8; DELETE FROM bookings WHERE bookingId BETWEEN 1 AND 8;

--changeset travelmate:0106-demo-notification-keys context:demo
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:1 SELECT COUNT(*) FROM users WHERE userId = '00000000-0000-4000-8000-000000000001'
--comment: Seeded notifications use i18n keys so they follow the reader's language
UPDATE notifications SET titleKey = 'notification.booking.confirmed.title', messageKey = 'notification.booking.confirmed.message', params = '[2, "Da Nang Beachfront Resort"]' WHERE user_id = '00000000-0000-4000-8000-000000000004' AND title = 'Đặt phòng thành công' AND titleKey IS NULL;
UPDATE notifications SET titleKey = 'notification.booking.cancelledRefundPending.title', messageKey = 'notification.booking.cancelledRefundPending.message', params = '[3]' WHERE user_id = '00000000-0000-4000-8000-000000000004' AND title = 'Đã hủy đặt phòng' AND titleKey IS NULL;
UPDATE notifications SET titleKey = 'notification.promotion.new.title', messageKey = 'notification.promotion.new.message', params = '["FLASH200K", 200000, 2000000]' WHERE user_id = '00000000-0000-4000-8000-000000000004' AND title = 'Ưu đãi mới' AND titleKey IS NULL;
UPDATE notifications SET titleKey = 'notification.account.rankUpDiamond.title', messageKey = 'notification.account.rankUpDiamond.message', params = NULL WHERE user_id = '00000000-0000-4000-8000-000000000005' AND title = 'Nâng hạng thành viên' AND titleKey IS NULL;
UPDATE notifications SET titleKey = 'notification.booking.received.title', messageKey = 'notification.booking.received.message', params = '[1, "Lê Hoàng Nam", "Hanoi Old Quarter Boutique Hotel"]' WHERE user_id = '00000000-0000-4000-8000-000000000002' AND title = 'Đơn đặt phòng mới #1' AND titleKey IS NULL;
UPDATE notifications SET titleKey = 'notification.admin.refundRequested.title', messageKey = 'notification.admin.refundRequested.message', params = '[3, 2590000]' WHERE user_id = '00000000-0000-4000-8000-000000000001' AND title = 'Yêu cầu hoàn tiền mới' AND titleKey IS NULL;
UPDATE notifications SET titleKey = 'notification.admin.ownerApplication.title', messageKey = 'notification.admin.ownerApplication.message', params = '["Hoàng Đức Anh"]' WHERE user_id = '00000000-0000-4000-8000-000000000001' AND title = 'Có đơn đăng ký Owner mới' AND titleKey IS NULL;
UPDATE notifications SET titleKey = 'notification.admin.propertySubmitted.title', messageKey = 'notification.admin.propertySubmitted.message', params = '["Trần Thị Lan", "Mui Ne Ocean Villa"]' WHERE user_id = '00000000-0000-4000-8000-000000000001' AND title = 'Có chỗ nghỉ mới chờ duyệt' AND titleKey IS NULL;
--rollback UPDATE notifications SET titleKey = NULL, messageKey = NULL, params = NULL WHERE user_id LIKE '00000000-0000-4000-8000-%';
