  (1, '00000000-0000-4000-8000-000000000002', '25 Hàng Bạc, Hoàn Kiếm, Hà Nội', 'Nam Định', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', '0109876543', '001085012345', '1985-07-20', 'APPROVED', 'Hồ sơ hợp lệ', '00000000-0000-4000-8000-000000000001', '2026-05-02 09:00:00', '2026-05-03 10:30:00'),
  (2, '00000000-0000-4000-8000-000000000003', '200 Võ Nguyên Giáp, Đà Nẵng', 'Quảng Nam', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', '0401234567', '048188012345', '1988-11-02', 'APPROVED', 'Hồ sơ hợp lệ', '00000000-0000-4000-8000-000000000001', '2026-05-10 14:00:00', '2026-05-11 08:15:00'),
  (3, '00000000-0000-4000-8000-000000000006', '12 Lạch Tray, Ngô Quyền, Hải Phòng', 'Hải Phòng', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1557750255-c76072a7aad1?w=1200&q=80&auto=format&fit=crop', '0201122334', '031099012345', '1999-09-14', 'PENDING', NULL, NULL, '2026-10-08 16:45:00', NULL);
INSERT INTO properties (propertyId, userId, propertyName, propertyType, propertyStatus, isActive, address, district, city, province, country, latitude, longitude, description, phoneContact, emailContact, rating, reviewCount, createdAt, updatedAt) VALUES
  (1, '00000000-0000-4000-8000-000000000002', 'Hanoi Old Quarter Boutique Hotel', 'HOTEL', 'APPROVE', b'1', '25 Hàng Bạc, Hoàn Kiếm, Hà Nội', 'Quận Hoàn Kiếm', 'Thành phố Hà Nội', 'Hà Nội', 'Việt Nam', 21.034000, 105.852000, 'Khách sạn boutique nằm giữa lòng phố cổ Hà Nội, chỉ 5 phút đi bộ tới Hồ Hoàn Kiếm. Phòng nghỉ ấm cúng mang phong cách Đông Dương, phục vụ bữa sáng phở truyền thống.', '0236000001', 'stay1@travelmate.vn', 5.0, 1, CURDATE(), CURDATE()),
  (2, '00000000-0000-4000-8000-000000000002', 'Sapa Valley View Homestay', 'HOMESTAY', 'APPROVE', b'1', 'Bản Cát Cát, Sa Pa, Lào Cai', 'Thị xã Sa Pa', 'Tỉnh Lào Cai', 'Lào Cai', 'Việt Nam', 22.325600, 103.835800, 'Homestay gỗ nguyên căn nhìn ra thung lũng Mường Hoa, lý tưởng cho nhóm bạn và gia đình. Có lò sưởi, bếp riêng và sân hiên ngắm ruộng bậc thang.', '0236000002', 'stay2@travelmate.vn', 4.0, 1, CURDATE(), CURDATE()),
  (3, '00000000-0000-4000-8000-000000000002', 'Ha Long Bay Pearl Hotel', 'HOTEL', 'APPROVE', b'1', '12 Đường Hạ Long, Bãi Cháy, Hạ Long, Quảng Ninh', 'Phường Bãi Cháy', 'Tỉnh Quảng Ninh', 'Quảng Ninh', 'Việt Nam', 20.952000, 107.045000, 'Khách sạn 4 sao hướng vịnh Hạ Long với hồ bơi vô cực trên tầng thượng. Gần cảng tàu du lịch và khu vui chơi Sun World.', '0236000003', 'stay3@travelmate.vn', 5.0, 1, CURDATE(), CURDATE()),
  (4, '00000000-0000-4000-8000-000000000002', 'Da Lat Pine Hill Villa', 'VILLA', 'APPROVE', b'1', '18 Trần Hưng Đạo, Phường 10, Đà Lạt, Lâm Đồng', 'Thành phố Đà Lạt', 'Tỉnh Lâm Đồng', 'Lâm Đồng', 'Việt Nam', 11.940000, 108.458000, 'Biệt thự nguyên căn giữa đồi thông Đà Lạt, 4 phòng ngủ, sân vườn BBQ và phòng khách có lò sưởi. Cách chợ Đà Lạt 10 phút lái xe.', '0236000004', 'stay4@travelmate.vn', 5.0, 1, CURDATE(), CURDATE()),
  (5, '00000000-0000-4000-8000-000000000003', 'Saigon Riverside Hotel', 'HOTEL', 'APPROVE', b'1', '88 Tôn Đức Thắng, Bến Nghé, Quận 1, TP. Hồ Chí Minh', 'Quận 1', 'Thành phố Hồ Chí Minh', 'Hồ Chí Minh', 'Việt Nam', 10.776900, 106.706000, 'Khách sạn ven sông Sài Gòn ngay trung tâm Quận 1, đi bộ tới phố đi bộ Nguyễn Huệ. Có quầy bar tầng thượng ngắm hoàng hôn.', '0236000005', 'stay5@travelmate.vn', 0.0, 0, CURDATE(), CURDATE()),
  (6, '00000000-0000-4000-8000-000000000003', 'Da Nang Beachfront Resort', 'RESORT', 'APPROVE', b'1', '200 Võ Nguyên Giáp, Mỹ An, Ngũ Hành Sơn, Đà Nẵng', 'Quận Ngũ Hành Sơn', 'Thành phố Đà Nẵng', 'Đà Nẵng', 'Việt Nam', 16.047000, 108.247000, 'Resort sát biển Mỹ Khê với bãi biển riêng, spa và ba hồ bơi. Thuận tiện đi Hội An, Bà Nà Hills và Cầu Vàng.', '0236000006', 'stay6@travelmate.vn', 0.0, 0, CURDATE(), CURDATE()),
  (7, '00000000-0000-4000-8000-000000000003', 'Hoi An Lantern Homestay', 'HOMESTAY', 'APPROVE', b'1', '45 Nguyễn Thị Minh Khai, Hội An, Quảng Nam', 'Thành phố Hội An', 'Tỉnh Quảng Nam', 'Quảng Nam', 'Việt Nam', 15.879000, 108.326000, 'Nhà cổ được cải tạo thành homestay nguyên căn, cách phố cổ Hội An 3 phút đi bộ. Có xe đạp miễn phí và lớp học nấu ăn cuối tuần.', '0236000007', 'stay7@travelmate.vn', 0.0, 0, CURDATE(), CURDATE()),
  (8, '00000000-0000-4000-8000-000000000003', 'Phu Quoc Sunset Resort', 'RESORT', 'APPROVE', b'1', 'Bãi Trường, Dương Tơ, Phú Quốc, Kiên Giang', 'Thành phố Phú Quốc', 'Tỉnh Kiên Giang', 'Kiên Giang', 'Việt Nam', 10.172000, 103.967000, 'Resort nghỉ dưỡng trên Bãi Trường với các bungalow hướng biển, nổi tiếng với hoàng hôn đẹp nhất đảo ngọc.', '0236000008', 'stay8@travelmate.vn', 4.0, 1, CURDATE(), CURDATE()),
  (9, '00000000-0000-4000-8000-000000000003', 'Mui Ne Ocean Villa', 'VILLA', 'PENDING', b'0', '79 Nguyễn Đình Chiểu, Hàm Tiến, Phan Thiết, Bình Thuận', 'Thành phố Phan Thiết', 'Tỉnh Bình Thuận', 'Bình Thuận', 'Việt Nam', 10.947000, 108.204000, 'Biệt thự biển mới khai trương tại Mũi Né, đang chờ quản trị viên duyệt.', '0236000009', 'stay9@travelmate.vn', 0.0, 0, CURDATE(), CURDATE());
