INSERT INTO PropertyAmenity (propertyId, amenityId, active) SELECT 1, amenityId, b'1' FROM Amenity WHERE amenityType = 'PROPERTY' AND amenityName IN ('wifi', 'ac', 'reception_24h', 'non_smoking', 'airport_transfer');
INSERT INTO PropertyAmenity (propertyId, amenityId, active) SELECT 2, amenityId, b'1' FROM Amenity WHERE amenityType = 'PROPERTY' AND amenityName IN ('wifi', 'parking', 'pets', 'non_smoking');
INSERT INTO PropertyAmenity (propertyId, amenityId, active) SELECT 3, amenityId, b'1' FROM Amenity WHERE amenityType = 'PROPERTY' AND amenityName IN ('pool', 'wifi', 'gym', 'ac', 'reception_24h', 'parking');
INSERT INTO PropertyAmenity (propertyId, amenityId, active) SELECT 4, amenityId, b'1' FROM Amenity WHERE amenityType = 'PROPERTY' AND amenityName IN ('wifi', 'parking', 'pets', 'ac');
