INSERT INTO rating (ratingId, bookings, users, rating, comment, ratingType, isHidden, is_pinned, createdAt) VALUES
  (1, 1, '00000000-0000-4000-8000-000000000004', 5, 'Vị trí tuyệt vời ngay phố cổ, nhân viên thân thiện, bữa sáng phở rất ngon. Chắc chắn sẽ quay lại!', 0, b'0', b'1', '2026-08-12 15:00:00'),
  (2, 4, '00000000-0000-4000-8000-000000000005', 4, 'Bungalow sạch sẽ, hoàng hôn đẹp mê hồn. Đồ ăn ở nhà hàng hơi đắt nhưng xứng đáng.', 0, b'0', b'0', '2026-07-17 15:00:00'),
  (3, 5, '00000000-0000-4000-8000-000000000005', 5, 'Biệt thự rộng rãi, sân vườn đẹp, cả nhà rất thích buổi BBQ tối. Chủ nhà hỗ trợ nhiệt tình.', 0, b'0', b'1', '2026-09-07 15:00:00'),
  (4, 7, '00000000-0000-4000-8000-000000000006', 4, 'View ruộng bậc thang đẹp như tranh, homestay ấm cúng. Đường vào hơi dốc nên cần đi xe máy cẩn thận.', 0, b'0', b'0', '2026-09-20 15:00:00'),
  (5, 8, '00000000-0000-4000-8000-000000000006', 5, 'Phòng hướng vịnh cực đẹp, hồ bơi tầng thượng là điểm cộng lớn. Gần cảng tàu rất tiện.', 0, b'0', b'0', '2026-08-24 15:00:00');
