  ('00000000-0000-4000-8000-000000000002', 'Đơn đặt phòng mới #1', 'Khách hàng Lê Hoàng Nam vừa đặt phòng tại Hanoi Old Quarter Boutique Hotel.', 'BOOKING_RECEIVED', '1', b'1', NOW(6)),
