  ('00000000-0000-4000-8000-000000000001', 'Có đơn đăng ký Owner mới', 'Hoàng Đức Anh vừa gửi đơn đăng ký trở thành chủ nhà.', 'ADMIN_NEW_OWNER_REGISTRATION', '3', b'0', NOW(6)),
